\title{The Canonical Class of a Pro-2 Demushkin Group and the
Characteristic-Two Linearization of the Cup Product}
\author{Aristotle}
\date{2026-07-06}

\begin{document}

\begin{abstract}
For a pro-$p$ Demushkin group $G$ the mod-$p$ cohomology is concentrated in
degrees $0,1,2$, with the cup product
$H^1(G;\FF_p)\times H^1(G;\FF_p)\to H^2(G;\FF_p)\cong\FF_p$ a nondegenerate
symmetric bilinear form. We study the first-order formality of the cochain
differential graded algebra $C^*(G;\Ftwo)$---equivalently, the vanishing of
the canonical class $c(G)$ in the second Hochschild cohomology of that
algebra---through the linear algebra of this cup-product form over the
two-element field $\Ftwo$. Our central observation is that in characteristic
two the self-cup map $q(x)=x\cup x$ is $\Ftwo$-linear, and hence, by
nondegeneracy, is represented by a unique cohomology class $\chi\in H^1$, the
\emph{Kummer (orientation) class}, characterized by $x\cup x=\chi\cup x$ for
all $x$. We prove that $\chi$ is well-defined and unique, that the form is
alternating (even type) if and only if $\chi=0$, and that nondegeneracy is
equivalently the statement that every nonzero class pairs nontrivially with
some class. We exhibit explicit forms realizing both Demushkin types---the
standard dot product (odd type, with $\chi$ the all-ones vector and isotropy
locus a hyperplane) and the hyperbolic plane (even type, fully
isotropic)---and connect the type dichotomy to the parity of the minimal
generating rank.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Demushkin groups}
A \emph{Demushkin group} is a pro-$p$ group $G$ whose mod-$p$ cohomology
satisfies: (1) $\dim_{\FF_p}H^1(G;\FF_p)$ is finite; (2)
$\dim_{\FF_p}H^2(G;\FF_p)=1$; and (3) the cup product
$H^1(G;\FF_p)\times H^1(G;\FF_p)\to H^2(G;\FF_p)$ is nondegenerate. Such groups
are the Galois groups of the maximal $p$-extension of a $p$-adic local field,
and (1)--(3) are the group-cohomological form of local Poincar\'e duality. All
cohomology in degrees $\ge 3$ vanishes, so $G$ has cohomological dimension two.

We specialize to $p=2$, write $\Ftwo=\mathbb Z/2\mathbb Z$, and set
$V:=H^1(G;\Ftwo)$ with $\dim_{\Ftwo}V=n<\infty$, and
$B:V\times V\to\Ftwo$, $B(x,y):=x\cup y$, the cup-product form
(identifying $H^2\cong\Ftwo$). By hypothesis $B$ is symmetric and nondegenerate.

\subsection{Formality and the canonical class}
The mod-2 cohomology is the homology of a differential graded algebra
$C^*(G;\Ftwo)$ of continuous cochains. The algebra is \emph{formal} if it is
quasi-isomorphic to its cohomology with zero differential; the first layer,
\emph{$A_3$-formality}, is governed by the Benson--Krause--Schwede canonical
class
$$
c(G)\in\HHtwo^2\!\big(C^*(G;\Ftwo),C^*(G;\Ftwo)\big),
$$
which vanishes if and only if $C^*(G;\Ftwo)$ is $A_3$-formal.

\medskip\noindent\textbf{Motivating conjecture.} \emph{For every pro-2
Demushkin group $G$, the canonical class $c(G)$ vanishes; equivalently
$C^*(G;\Ftwo)$ is $A_3$-formal.}

\subsection{Reduction to finite linear algebra}
Because $G$ has cohomological dimension two, every secondary operation of arity
$\ge 4$ lands in $H^{\ge 3}=0$. The only potentially nontrivial secondary
operation is the ternary one, $H^1\otimes H^1\otimes H^1\to H^2$ of degree
$1+1+1-1=2$, assembled from the cup product. Thus the entire first-order
formality obstruction is encoded in the linear algebra of $(V,B)$.

\section{The squaring functional in characteristic two}

\begin{definition}[Self-cup map]
For a symmetric bilinear form $B$ on an $\Ftwo$-vector space $V$, define
$q:V\to\Ftwo$, $q(x):=B(x,x)=x\cup x$.
\end{definition}

\begin{theorem}[Characteristic-two linearity]\label{thm:lin}
The self-cup map $q$ is $\Ftwo$-linear; i.e.\ $q\in V^*=\Hom_{\Ftwo}(V,\Ftwo)$.
\end{theorem}
\begin{proof}
By bilinearity and symmetry,
$q(x+y)=B(x,x)+B(x,y)+B(y,x)+B(y,y)=q(x)+2B(x,y)+q(y)$; in $\Ftwo$, $2=0$, so
$q(x+y)=q(x)+q(y)$. For $c\in\Ftwo$, $q(cx)=c^2q(x)$ and $c^2=c$, so
$q(cx)=c\,q(x)$.
\end{proof}

Over any field of characteristic $\ne 2$ the cross term $2B(x,y)$ is the
polarization making $q$ quadratic; its vanishing is what ultimately trivializes
the ternary secondary operation.

\begin{definition}
$B$ is \emph{nondegenerate} if $B(a,x)=0$ for all $x$ implies $a=0$;
equivalently the map $B^\flat:V\to V^*$, $B^\flat(v)=B(v,-)$, is injective (an
isomorphism in finite dimension).
\end{definition}

\begin{proposition}[Detection form of nondegeneracy]\label{prop:detect}
If $B$ is nondegenerate and $a\ne 0$, there exists $x$ with $B(a,x)=1$.
\end{proposition}
\begin{proof}
If not, then $B(a,x)\ne 1$ forces $B(a,x)=0$ for all $x$ (values lie in
$\{0,1\}$), whence $a=0$, a contradiction.
\end{proof}

\section{The Kummer (orientation) class}

Assume $V$ finite-dimensional, $B$ symmetric and nondegenerate, so
$B^\flat:V\xrightarrow{\sim}V^*$.

\begin{definition}[Kummer class]
The \emph{Kummer (orientation) class} is $\chi:=(B^\flat)^{-1}(q)$; equivalently
$B(\chi,-)=q$.
\end{definition}

\begin{theorem}[Defining property]\label{thm:spec}
For all $x\in V$, $B(\chi,x)=B(x,x)$; equivalently $\chi\cup x=x\cup x$.
\end{theorem}
\begin{proof}
$B^\flat(\chi)=q$; evaluate at $x$: $B(\chi,x)=q(x)=B(x,x)$.
\end{proof}

\begin{theorem}[Uniqueness]\label{thm:uniq}
If $B(w,x)=B(x,x)$ for all $x$, then $w=\chi$.
\end{theorem}
\begin{proof}
$B(w-\chi,x)=B(x,x)-B(x,x)=0$ for all $x$; nondegeneracy gives $w=\chi$.
\end{proof}

The Kummer class uses only the two Demushkin axioms: symmetry (for
Theorem~\ref{thm:lin}) and nondegeneracy (for representability). It is the
linear-algebra shadow of $c(G)$.

\section{The type dichotomy}

\begin{definition}
$B$ is \emph{alternating} if $B(x,x)=0$ for all $x$. A Demushkin group is of
\emph{even (orientable) type} if $B$ is alternating, and of \emph{odd type}
otherwise.
\end{definition}

\begin{theorem}[Type dichotomy]\label{thm:dich}
$B$ is alternating if and only if $\chi=0$.
\end{theorem}
\begin{proof}
If $B(x,x)=0$ for all $x$ then $q=0$ so $\chi=0$. Conversely if $\chi=0$ then
$B(x,x)=B(\chi,x)=0$ by Theorem~\ref{thm:spec}.
\end{proof}

\begin{remark}[Parity of the rank]\label{rem:parity}
A nondegenerate alternating form over any field decomposes into hyperbolic
planes, hence exists only in even dimension. Thus every even-type pro-2
Demushkin group has even minimal generating rank $n=\dim_{\Ftwo}V$; odd rank
forces the odd type.
\end{remark}

\section{Realizations: both types occur}

\subsection{The dot product---odd type}
\begin{definition}
On $V=\Ftwo^n$, $B_{\mathrm{dot}}(x,y)=\sum_{i=1}^n x_iy_i$.
\end{definition}
\begin{proposition}
$B_{\mathrm{dot}}$ is symmetric and nondegenerate. For $n\ge 1$ it is not
alternating (odd type). Its Kummer class is $\chi=(1,\dots,1)$, and its isotropy
locus $\{x:B_{\mathrm{dot}}(x,x)=0\}=\{x:\sum_i x_i=0\}$ is the even-weight
hyperplane of codimension one.
\end{proposition}
\begin{proof}
Nondegeneracy: pairing $B_{\mathrm{dot}}(a,-)=0$ against $e_i$ gives $a_i=0$.
Non-alternating: $B_{\mathrm{dot}}(e_1,e_1)=1$. Over $\Ftwo$, $x_i^2=x_i$, so
$B_{\mathrm{dot}}(x,x)=\sum_i x_i=B_{\mathrm{dot}}(\mathbf 1,x)$; uniqueness
(Theorem~\ref{thm:uniq}) gives $\chi=\mathbf 1$. The isotropy locus is
$\ker q$, a codimension-one hyperplane.
\end{proof}

\subsection{The hyperbolic plane---even type}
\begin{definition}
On $V=\Ftwo^2$, $B_{\mathrm{hyp}}$ has Gram matrix
$\left(\begin{smallmatrix}0&1\\1&0\end{smallmatrix}\right)$.
\end{definition}
\begin{proposition}
$B_{\mathrm{hyp}}$ is symmetric, nondegenerate, and alternating (even type),
with $\chi=0$ and isotropy locus all of $V$.
\end{proposition}
\begin{proof}
The Gram matrix is symmetric and invertible ($\det=1$). For $x=ae_1+be_2$,
$B_{\mathrm{hyp}}(x,x)=2ab=0$; by Theorem~\ref{thm:dich}, $\chi=0$.
\end{proof}

\section{Algorithms}
Given a Gram matrix $M\in\Ftwo^{n\times n}$ of $B$:
\begin{itemize}
\item \textbf{Kummer class.} $q(x)=x^\top Mx=\sum_i M_{ii}x_i$ (cross terms
cancel), represented by $d=\diag(M)$; solve $M\chi=d$ over $\Ftwo$ ($O(n^3)$).
\item \textbf{Type test.} Even iff $\chi=0$ iff $d=0$.
\item \textbf{Isotropy locus.} $\{x:d^\top x=0\}=\ker(d^\top)$: a
codimension-one hyperplane if $d\ne 0$, all of $V$ if $d=0$.
\end{itemize}

\section{Discussion}
The passage $C^*(G;\Ftwo)\rightsquigarrow(V,B)\rightsquigarrow\chi$ is a triple
compression: cohomological dimension two forces the obstruction into the
ternary cup operation; characteristic two makes squaring linear
(Theorem~\ref{thm:lin}); nondegeneracy represents that functional by the unique
Kummer class. The motivating conjecture $c(G)=0$ is reflected by the linearity
of $q$: because $q$ is linear rather than quadratic, the ternary secondary
operation is unobstructed, while the even/odd dichotomy detected by $\chi$
classifies the two structural regimes.

\section{Future work}
\begin{itemize}
\item The orientation class as mod-2 defining exponent.
\item Even type forces even rank (Remark~\ref{rem:parity} as a structure
theorem).
\item Vanishing of all higher secondary operations (full formality).
\item The isotropy hyperplane as an arithmetic invariant of odd-type groups.
\end{itemize}

\end{document}

